insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_keratoconus', 'Keratoconus', 'Queratocono', ARRAY['KC', 'corneal ectasia']::text[], ARRAY['KC', 'ectasia corneal']::text[], ARRAY['H18.6']::text[], 'Progressive non-inflammatory corneal ectasia characterised by corneal thinning, protrusion and irregular astigmatism.', 'Ectasia corneal progresiva no inflamatoria con adelgazamiento, protrusión y astigmatismo irregular.', 'Prevalence varies by population and diagnostic method; often diagnosed in adolescence or early adulthood.', 'Eye rubbing, atopy, family history, Down syndrome, connective tissue disease and genetic predisposition.', 'Progressive myopia/astigmatism, reduced best-corrected vision, scissoring reflex, corneal thinning, Fleischer ring, Vogt striae, apical scarring in advanced cases.', 'Refraction, slit lamp, keratometry, corneal topography/tomography, pachymetry, posterior elevation, epithelial mapping when available.', 'Spectacles or contact lenses for visual rehabilitation; corneal cross-linking for documented progression; intracorneal ring segments, phakic IOL or keratoplasty in selected cases.', 'Monitor progression with serial tomography, refraction and visual acuity; shorter intervals in young/progressive patients.', 'Rapid progression, acute hydrops, apical scarring, intolerance to contact lenses or advanced thinning.', 'guideline', 'AAO PPP and global consensus support tomography-based diagnosis and cross-linking for progressive disease.', '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}, {"title": "Global consensus on keratoconus and ectatic diseases", "url": "https://pubmed.ncbi.nlm.nih.gov/25738235/"}, {"title": "Belin ABCD keratoconus classification and staging evidence", "url": "https://pubmed.ncbi.nlm.nih.gov/29753871/"}]'::jsonb, 'Prevalence varies by population and diagnostic method; often diagnosed in adolescence or early adulthood.', 'Eye rubbing, atopy, family history, Down syndrome, connective tissue disease and genetic predisposition.', 'Progressive myopia/astigmatism, reduced best-corrected vision, scissoring reflex, corneal thinning, Fleischer ring, Vogt striae, apical scarring in advanced cases.', 'Refraction, slit lamp, keratometry, corneal topography/tomography, pachymetry, posterior elevation, epithelial mapping when available.', 'Spectacles or contact lenses for visual rehabilitation; corneal cross-linking for documented progression; intracorneal ring segments, phakic IOL or keratoplasty in selected cases.', 'Monitor progression with serial tomography, refraction and visual acuity; shorter intervals in young/progressive patients.', 'Rapid progression, acute hydrops, apical scarring, intolerance to contact lenses or advanced thinning.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_pellucid_marginal_degeneration', 'Pellucid marginal degeneration', 'Degeneración marginal pelúcida', ARRAY['PMD', 'inferior pellucid ectasia']::text[], ARRAY['DMP', 'ectasia pelúcida inferior']::text[], ARRAY['H18.6']::text[], 'Peripheral inferior corneal ectatic disorder with band-like thinning and against-the-rule astigmatism.', 'Ectasia periférica inferior con adelgazamiento en banda y astigmatismo contra la regla.', 'Uncommon ectatic disorder, usually presenting in adulthood.', 'Unknown; may overlap with keratoconus spectrum.', 'High against-the-rule astigmatism, inferior thinning above limbus, crab-claw pattern on topography.', 'Slit lamp, topography/tomography, pachymetry and differential diagnosis with keratoconus.', 'Spectacles/RGP/scleral lenses, cross-linking in selected progressive cases, keratoplasty when advanced.', 'Tomographic monitoring for progression.', 'Progressive thinning, hydrops, poor visual rehabilitation.', 'guideline', 'Included within corneal ectasia spectrum in AAO PPP.', '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}, {"title": "Global consensus on keratoconus and ectatic diseases", "url": "https://pubmed.ncbi.nlm.nih.gov/25738235/"}]'::jsonb, 'Uncommon ectatic disorder, usually presenting in adulthood.', 'Unknown; may overlap with keratoconus spectrum.', 'High against-the-rule astigmatism, inferior thinning above limbus, crab-claw pattern on topography.', 'Slit lamp, topography/tomography, pachymetry and differential diagnosis with keratoconus.', 'Spectacles/RGP/scleral lenses, cross-linking in selected progressive cases, keratoplasty when advanced.', 'Tomographic monitoring for progression.', 'Progressive thinning, hydrops, poor visual rehabilitation.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_post_lasik_ectasia', 'Post-LASIK / post-refractive corneal ectasia', 'Ectasia corneal post-LASIK / post-refractiva', ARRAY['iatrogenic ectasia', 'postoperative ectasia']::text[], ARRAY['ectasia iatrogénica', 'ectasia postoperatoria']::text[], 'Progressive corneal steepening, thinning and irregular astigmatism after corneal refractive surgery.', 'Aumento progresivo de curvatura, adelgazamiento y astigmatismo irregular tras cirugía refractiva corneal.', 'Rare but vision-threatening complication; risk depends on preoperative corneal characteristics and surgical parameters.', 'Abnormal topography, thin residual stromal bed, high myopia correction, young age, forme fruste keratoconus and low biomechanical reserve.', 'Progressive regression, irregular astigmatism, reduced corrected vision and ectatic tomographic changes.', 'Pre/postoperative tomography comparison, pachymetry, epithelial maps, biomechanical assessment if available.', 'Cross-linking for progression, specialty lenses, topography-guided PRK plus CXL in selected cases, keratoplasty rarely.', 'Serial tomography and refraction to assess stability.', 'Rapid progression after surgery, severe thinning or contact lens failure.', 'guideline', 'AAO ectasia PPP includes post-refractive ectasia risk and management concepts.', '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}]'::jsonb, 'Rare but vision-threatening complication; risk depends on preoperative corneal characteristics and surgical parameters.', 'Abnormal topography, thin residual stromal bed, high myopia correction, young age, forme fruste keratoconus and low biomechanical reserve.', 'Progressive regression, irregular astigmatism, reduced corrected vision and ectatic tomographic changes.', 'Pre/postoperative tomography comparison, pachymetry, epithelial maps, biomechanical assessment if available.', 'Cross-linking for progression, specialty lenses, topography-guided PRK plus CXL in selected cases, keratoplasty rarely.', 'Serial tomography and refraction to assess stability.', 'Rapid progression after surgery, severe thinning or contact lens failure.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_bacterial_keratitis', 'Bacterial keratitis', 'Queratitis bacteriana', ARRAY['bacterial corneal ulcer', 'microbial keratitis']::text[], ARRAY['úlcera corneal bacteriana', 'queratitis microbiana']::text[], ARRAY['H16.0']::text[], 'Potentially sight-threatening corneal infection caused by bacteria with epithelial defect and stromal infiltrate.', 'Infección corneal potencialmente grave por bacterias con defecto epitelial e infiltrado estromal.', 'Contact lens wear is a major risk factor in developed settings; trauma and ocular surface disease are common contributors.', 'Contact lens wear, trauma, ocular surface disease, topical steroid use, prior surgery, exposure and immunosuppression.', 'Pain, redness, photophobia, discharge, epithelial defect, stromal infiltrate, anterior chamber reaction or hypopyon in severe cases.', 'Slit-lamp documentation, fluorescein staining, cultures/scrapes for large, central, severe, atypical or nonresponding ulcers.', 'Urgent broad-spectrum topical antibiotics; adjust to severity, microbiology and response; avoid inappropriate steroid timing.', 'Frequent review initially, with monitoring of epithelial defect, infiltrate size, thinning and AC reaction.', 'Central ulcer, rapid progression, thinning/perforation, hypopyon, contact lens-associated Pseudomonas risk, poor response.', 'guideline', 'Clinical management guidelines emphasize emergency referral and evidence-based antimicrobial management.', '[{"title": "College of Optometrists Clinical Management Guideline: Microbial keratitis bacterial/fungal", "url": "https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_bacterial_fungal"}, {"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'Contact lens wear is a major risk factor in developed settings; trauma and ocular surface disease are common contributors.', 'Contact lens wear, trauma, ocular surface disease, topical steroid use, prior surgery, exposure and immunosuppression.', 'Pain, redness, photophobia, discharge, epithelial defect, stromal infiltrate, anterior chamber reaction or hypopyon in severe cases.', 'Slit-lamp documentation, fluorescein staining, cultures/scrapes for large, central, severe, atypical or nonresponding ulcers.', 'Urgent broad-spectrum topical antibiotics; adjust to severity, microbiology and response; avoid inappropriate steroid timing.', 'Frequent review initially, with monitoring of epithelial defect, infiltrate size, thinning and AC reaction.', 'Central ulcer, rapid progression, thinning/perforation, hypopyon, contact lens-associated Pseudomonas risk, poor response.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_fungal_keratitis', 'Fungal keratitis', 'Queratitis fúngica', ARRAY['mycotic keratitis', 'fungal corneal ulcer']::text[], ARRAY['queratitis micótica', 'úlcera corneal fúngica']::text[], ARRAY['H16.0']::text[], 'Corneal infection caused by filamentous fungi or yeasts, often associated with trauma, agriculture or immunosuppression.', 'Infección corneal por hongos filamentosos o levaduras, a menudo asociada a trauma vegetal o inmunosupresión.', 'More frequent in tropical/agricultural settings; increasing recognition globally.', 'Vegetative trauma, contact lens wear, topical corticosteroids, ocular surface disease, surgery and immunosuppression.', 'Feathery infiltrate borders, satellite lesions, endothelial plaque, hypopyon, indolent course; yeasts may mimic bacterial ulcers.', 'Corneal scraping for microscopy/culture; consider confocal microscopy and PCR where available.', 'Topical antifungal therapy guided by organism; natamycin for many filamentous fungi, amphotericin/voriconazole depending on context; surgery if perforation or progression.', 'Close review because response is slow and complications frequent.', 'Deep stromal involvement, thinning, endothelial plaque, perforation risk, no response to therapy.', 'guideline', 'Microbial keratitis guidelines cover fungal keratitis as sight-threatening infection requiring urgent specialist management.', '[{"title": "College of Optometrists Clinical Management Guideline: Microbial keratitis bacterial/fungal", "url": "https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_bacterial_fungal"}]'::jsonb, 'More frequent in tropical/agricultural settings; increasing recognition globally.', 'Vegetative trauma, contact lens wear, topical corticosteroids, ocular surface disease, surgery and immunosuppression.', 'Feathery infiltrate borders, satellite lesions, endothelial plaque, hypopyon, indolent course; yeasts may mimic bacterial ulcers.', 'Corneal scraping for microscopy/culture; consider confocal microscopy and PCR where available.', 'Topical antifungal therapy guided by organism; natamycin for many filamentous fungi, amphotericin/voriconazole depending on context; surgery if perforation or progression.', 'Close review because response is slow and complications frequent.', 'Deep stromal involvement, thinning, endothelial plaque, perforation risk, no response to therapy.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_acanthamoeba_keratitis', 'Acanthamoeba keratitis', 'Queratitis por Acanthamoeba', ARRAY['AK', 'protozoal keratitis']::text[], ARRAY['QA', 'queratitis protozoaria']::text[], ARRAY['B60.1', 'H19.2']::text[], 'Sight-threatening protozoal keratitis classically associated with contact lens exposure to water and delayed diagnosis.', 'Queratitis protozoaria grave clásicamente asociada al uso de lentes de contacto y exposición al agua.', 'Rare but important cause of severe keratitis; contact lens water exposure is a key preventable risk.', 'Contact lenses, water exposure, poor lens hygiene, orthokeratology, corneal trauma.', 'Pain disproportionate to signs, radial perineuritis, pseudodendrites, ring infiltrate in later stages, chronic course.', 'High suspicion; confocal microscopy, corneal scraping/culture/PCR where available.', 'Early biguanide-based anti-amoebic therapy; prolonged treatment and specialist follow-up; keratoplasty for selected complications.', 'Frequent review and prolonged monitoring for recurrence.', 'Severe pain, ring infiltrate, scleritis, delayed diagnosis, thinning/perforation.', 'guideline', 'College of Optometrists guideline highlights emergency referral and diagnostic considerations.', '[{"title": "College of Optometrists Clinical Management Guideline: Acanthamoeba keratitis", "url": "https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_acanthamoebasp"}]'::jsonb, 'Rare but important cause of severe keratitis; contact lens water exposure is a key preventable risk.', 'Contact lenses, water exposure, poor lens hygiene, orthokeratology, corneal trauma.', 'Pain disproportionate to signs, radial perineuritis, pseudodendrites, ring infiltrate in later stages, chronic course.', 'High suspicion; confocal microscopy, corneal scraping/culture/PCR where available.', 'Early biguanide-based anti-amoebic therapy; prolonged treatment and specialist follow-up; keratoplasty for selected complications.', 'Frequent review and prolonged monitoring for recurrence.', 'Severe pain, ring infiltrate, scleritis, delayed diagnosis, thinning/perforation.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_hsv_epithelial_keratitis', 'HSV epithelial keratitis', 'Queratitis epitelial por herpes simple', ARRAY['dendritic keratitis', 'herpes simplex keratitis']::text[], ARRAY['queratitis dendrítica', 'queratitis herpética']::text[], ARRAY['B00.5']::text[], 'Corneal epithelial infection due to herpes simplex virus, often presenting with dendritic epithelial ulceration.', 'Infección epitelial corneal por virus herpes simple, con úlcera dendrítica característica.', 'HSV keratitis is a leading infectious cause of corneal blindness worldwide.', 'Prior HSV, immunosuppression, topical steroids without antiviral cover, ocular trauma or surgery.', 'Dendritic ulcer with terminal bulbs, reduced corneal sensation, foreign body sensation, photophobia and redness.', 'Clinical slit-lamp diagnosis with fluorescein/rose bengal/lissamine where appropriate; PCR in atypical cases.', 'Topical or oral antiviral therapy; avoid topical steroid in active epithelial disease unless specialist-directed.', 'Ensure epithelial healing and monitor for stromal/endothelial involvement.', 'Geographic ulcer, stromal keratitis, uveitis, raised IOP, immunosuppression or poor response.', 'educational_reference', 'NCBI/StatPearls and AAO benchmark resources describe HSV keratitis as common and potentially blinding.', '[{"title": "NCBI Bookshelf: Herpes Simplex Keratitis", "url": "https://www.ncbi.nlm.nih.gov/books/NBK545278/"}, {"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'HSV keratitis is a leading infectious cause of corneal blindness worldwide.', 'Prior HSV, immunosuppression, topical steroids without antiviral cover, ocular trauma or surgery.', 'Dendritic ulcer with terminal bulbs, reduced corneal sensation, foreign body sensation, photophobia and redness.', 'Clinical slit-lamp diagnosis with fluorescein/rose bengal/lissamine where appropriate; PCR in atypical cases.', 'Topical or oral antiviral therapy; avoid topical steroid in active epithelial disease unless specialist-directed.', 'Ensure epithelial healing and monitor for stromal/endothelial involvement.', 'Geographic ulcer, stromal keratitis, uveitis, raised IOP, immunosuppression or poor response.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_hsv_stromal_keratitis', 'HSV stromal keratitis', 'Queratitis estromal herpética', ARRAY['herpetic stromal keratitis', 'immune stromal keratitis']::text[], ARRAY['queratitis estromal por VHS', 'queratitis inmune herpética']::text[], ARRAY['B00.5']::text[], 'Immune-mediated or necrotising stromal inflammation related to HSV infection that can scar the cornea.', 'Inflamación estromal inmunomediada o necrotizante relacionada con VHS que puede cicatrizar la córnea.', 'Major cause of recurrent corneal scarring in HSV eye disease.', 'Recurrent HSV, previous stromal disease, steroid misuse, immune dysregulation.', 'Stromal haze/infiltrate, oedema, neovascularisation, reduced vision, possible epithelial disease or uveitis.', 'Slit lamp, corneal sensation, IOP and assessment for epithelial activity; consider PCR if atypical.', 'Specialist-directed anti-inflammatory therapy with antiviral cover; long-term prophylaxis in recurrent disease may be considered.', 'Close follow-up for IOP, epithelial status, stromal inflammation and scarring.', 'Necrotising keratitis, thinning, uveitis/trabeculitis, high IOP or impending perforation.', 'educational_reference', 'HSV keratitis references emphasise recurrence, stromal scarring and blindness risk.', '[{"title": "NCBI Bookshelf: Herpes Simplex Keratitis", "url": "https://www.ncbi.nlm.nih.gov/books/NBK545278/"}, {"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'Major cause of recurrent corneal scarring in HSV eye disease.', 'Recurrent HSV, previous stromal disease, steroid misuse, immune dysregulation.', 'Stromal haze/infiltrate, oedema, neovascularisation, reduced vision, possible epithelial disease or uveitis.', 'Slit lamp, corneal sensation, IOP and assessment for epithelial activity; consider PCR if atypical.', 'Specialist-directed anti-inflammatory therapy with antiviral cover; long-term prophylaxis in recurrent disease may be considered.', 'Close follow-up for IOP, epithelial status, stromal inflammation and scarring.', 'Necrotising keratitis, thinning, uveitis/trabeculitis, high IOP or impending perforation.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_hzv_keratitis', 'Herpes zoster ophthalmicus keratitis', 'Queratitis por herpes zóster oftálmico', ARRAY['HZO keratitis', 'varicella zoster keratitis']::text[], ARRAY['queratitis por HZO', 'queratitis por varicela zóster']::text[], ARRAY['B02.3']::text[], 'Corneal involvement in ophthalmic division varicella-zoster infection, including epithelial, stromal, endothelial and neurotrophic forms.', 'Afectación corneal en infección por virus varicela-zóster de la división oftálmica.', 'Risk increases with age and immunosuppression.', 'Older age, immunosuppression, prior zoster, lack of vaccination.', 'Dermatomal rash, Hutchinson sign, punctate/dendriform epithelial lesions, stromal keratitis, uveitis, reduced sensation.', 'Clinical exam including skin, cornea, anterior chamber, IOP and corneal sensation.', 'Systemic antiviral therapy early; manage inflammation, epithelial disease, uveitis and neurotrophic complications under specialist care.', 'Monitor for chronic keratitis, uveitis, IOP and neurotrophic keratopathy.', 'Immunosuppression, ocular involvement with severe pain/vision loss, keratouveitis, neurotrophic ulcer.', 'educational_reference', 'AAO and cornea external benchmarks support prompt antiviral and ocular evaluation principles.', '[{"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'Risk increases with age and immunosuppression.', 'Older age, immunosuppression, prior zoster, lack of vaccination.', 'Dermatomal rash, Hutchinson sign, punctate/dendriform epithelial lesions, stromal keratitis, uveitis, reduced sensation.', 'Clinical exam including skin, cornea, anterior chamber, IOP and corneal sensation.', 'Systemic antiviral therapy early; manage inflammation, epithelial disease, uveitis and neurotrophic complications under specialist care.', 'Monitor for chronic keratitis, uveitis, IOP and neurotrophic keratopathy.', 'Immunosuppression, ocular involvement with severe pain/vision loss, keratouveitis, neurotrophic ulcer.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (slug, name_en, name_es, synonyms_en, synonyms_es, icd10_codes, definition_en, definition_es, epidemiology_en, risk_factors_en, clinical_features_en, diagnostic_workup_en, treatment_overview_en, follow_up_en, red_flags_en, evidence_level, source_summary, references_json, epidemiology_es, risk_factors_es, clinical_features_es, diagnostic_workup_es, treatment_overview_es, follow_up_es, red_flags_es, subspecialty, status, is_active, metadata) values ('cornea_neurotrophic_keratitis', 'Neurotrophic keratitis', 'Queratitis neurotrófica', ARRAY['NK', 'neurotrophic keratopathy']::text[], ARRAY['QN', 'queratopatía neurotrófica']::text[], ARRAY['H16.2']::text[], 'Degenerative corneal disease caused by impaired trigeminal innervation leading to epithelial breakdown, poor healing and ulceration.', 'Enfermedad corneal degenerativa por alteración de la inervación trigeminal con defectos epiteliales y mala cicatrización.', 'Rare but potentially blinding; caused by herpetic disease, surgery, diabetes, tumours or neurotrophic insults.', 'HSV/HZV, diabetes, neurosurgery, acoustic neuroma, chemical burns, chronic topical toxicity and severe ocular surface disease.', 'Reduced corneal sensation, persistent epithelial defect, ulceration with relatively little pain, stromal melting in severe cases.', 'Corneal sensitivity testing, fluorescein staining, assessment of epithelial defect/ulcer and underlying cause.', 'Preservative-free lubrication, stop toxic drops, therapeutic contact lens/amniotic membrane/tarsorrhaphy; cenegermin for moderate/severe disease where approved.', 'Frequent monitoring until epithelial closure, then long-term protection.', 'Persistent epithelial defect, stromal thinning, corneal melt, perforation risk.', 'educational_reference', 'EMA Oxervate indication: moderate or severe neurotrophic keratitis in adults.', '[{"title": "EMA Oxervate EPAR", "url": "https://www.ema.europa.eu/en/medicines/human/EPAR/oxervate"}, {"title": "EMA Oxervate product information", "url": "https://www.ema.europa.eu/en/documents/product-information/oxervate-epar-product-information_en.pdf"}, {"title": "Neurotrophic keratopathy clinical presentation and cenegermin outcomes review", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8938625/"}]'::jsonb, 'Rare but potentially blinding; caused by herpetic disease, surgery, diabetes, tumours or neurotrophic insults.', 'HSV/HZV, diabetes, neurosurgery, acoustic neuroma, chemical burns, chronic topical toxicity and severe ocular surface disease.', 'Reduced corneal sensation, persistent epithelial defect, ulceration with relatively little pain, stromal melting in severe cases.', 'Corneal sensitivity testing, fluorescein staining, assessment of epithelial defect/ulcer and underlying cause.', 'Preservative-free lubrication, stop toxic drops, therapeutic contact lens/amniotic membrane/tarsorrhaphy; cenegermin for moderate/severe disease where approved.', 'Frequent monitoring until epithelial closure, then long-term protection.', 'Persistent epithelial defect, stromal thinning, corneal melt, perforation risk.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
