ct do nothing;
insert into public.oph_medications (generic_name_en, generic_name_es, brand_names, medication_class, route, mechanism_en, common_uses_en, contraindications_en, warnings_en, adverse_effects_en, monitoring_en, pregnancy_lactation_notes, regulatory_notes, is_prescription, is_intravitreal, is_surgical_adjuvant, references_json, mechanism_es, common_uses_es, contraindications_es, warnings_es, adverse_effects_es, monitoring_es, status, is_active, metadata) values ('Riboflavin with UVA corneal cross-linking', 'Riboflavina con UVA para cross-linking corneal', ARRAY['Photrexa', 'riboflavin solutions']::text[], 'other', 'topical', 'Photosensitised collagen cross-link formation increases corneal biomechanical stability.', 'Progressive keratoconus and corneal ectasia where approved.', 'Insufficient corneal thickness or contraindications per protocol/label; active infection.', 'Requires controlled UVA device/protocol; haze, infection and endothelial safety considerations.', 'Pain, haze, delayed epithelial healing, infection rare, sterile infiltrates.', 'Epithelial healing, haze, tomography stability and visual rehabilitation.', 'Usually elective; consult local guidance.', 'FDA-approved Photrexa/KXL for progressive keratoconus and post-refractive ectasia; CE/local status varies by device/product.', true, false, true, '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}, {"title": "FDA Photrexa / KXL approval information for corneal cross-linking", "url": "https://www.accessdata.fda.gov/drugsatfda_docs/label/2016/203324s000lbl.pdf"}]'::jsonb, 'Photosensitised collagen cross-link formation increases corneal biomechanical stability.', 'Progressive keratoconus and corneal ectasia where approved.', 'Insufficient corneal thickness or contraindications per protocol/label; active infection.', 'Requires controlled UVA device/protocol; haze, infection and endothelial safety considerations.', 'Pain, haze, delayed epithelial healing, infection rare, sterile infiltrates.', 'Epithelial healing, haze, tomography stability and visual rehabilitation.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Corneal Ectasia Preferred Practice Pattern', 'American Academy of Ophthalmology', 'USA / international reference', 'preferred_practice_pattern', 'cornea', 2024, '2024 update PDF', 'https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf', 'American Academy of Ophthalmology. Corneal Ectasia Preferred Practice Pattern.', 'Evidence-based PPP for keratoconus and corneal ectatic disorders, including diagnosis, monitoring and cross-linking concepts.', 'PPP basada en evidencia para queratocono y ectasias corneales, con diagnóstico, seguimiento y cross-linking.', 'Use tomography for diagnosis/progression; cross-linking is key for progressive keratoconus; tailor visual rehabilitation.', 'Usar tomografía para diagnóstico/progresión; cross-linking en queratocono progresivo; rehabilitación visual individualizada.', 'Do not reproduce PPP text verbatim; cite and summarise.', 'AAO copyright applies; use URL and original summary only.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Cornea/External Disease Summary Benchmarks', 'American Academy of Ophthalmology', 'USA / international reference', 'society_recommendation', 'cornea', 2025, 'Summary benchmark page', 'https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020', 'AAO Cornea/External Disease Summary Benchmarks.', 'AAO benchmark resource summarising cornea/external disease practice patterns.', 'Recurso AAO con benchmarks de córnea y enfermedad externa.', 'Useful umbrella reference for corneal infections, external disease and ocular surface safety.', 'Referencia marco para infecciones corneales, enfermedad externa y seguridad de superficie.', 'Use as benchmark index, not as full guideline reproduction.', 'AAO copyright applies.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Clinical Management Guideline: Microbial keratitis bacterial/fungal', 'College of Optometrists', 'UK', 'clinical_guideline', 'cornea', 2025, 'Online CMG', 'https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_bacterial_fungal', 'College of Optometrists. Microbial keratitis bacterial/fungal clinical management guideline.', 'Guideline outlining aetiology, symptoms, signs and evidence-based recommendations for microbial keratitis.', 'Guía sobre etiología, síntomas, signos y recomendaciones de queratitis microbiana.', 'Recognise sight-threatening infection; urgent referral/management; culture severe/atypical/nonresponding ulcers.', 'Reconocer infección grave; derivación/manejo urgente; cultivo en úlceras severas/atípicas/no respondedoras.', 'Use summary and URL; verify update date in live page.', 'Do not reproduce full guideline.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Clinical Management Guideline: Acanthamoeba keratitis', 'College of Optometrists', 'UK', 'clinical_guideline', 'cornea', 2025, 'Online CMG', 'https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_acanthamoebasp', 'College of Optometrists. Acanthamoeba keratitis clinical management guideline.', 'Guideline covering aetiology, signs, symptoms and referral for Acanthamoeba keratitis.', 'Guía sobre etiología, signos, síntomas y derivación en queratitis por Acanthamoeba.', 'High suspicion in contact lens/water exposure; emergency referral; early diagnostic testing.', 'Alta sospecha en lentes de contacto/exposición al agua; derivación urgente; pruebas diagnósticas tempranas.', 'Use original summary only.', 'Do not reproduce full guideline.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, doi, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('TFOS DEWS II Definition and Classification Report', 'Tear Film & Ocular Surface Society', 'International', 'consensus_statement', 'cornea', 2017, 'DEWS II', 'https://pubmed.ncbi.nlm.nih.gov/28736335/', '10.1016/j.jtos.2017.05.008', 'Craig JP et al. TFOS DEWS II Definition and Classification Report. Ocul Surf. 2017.', 'Consensus definition and classification of dry eye disease based on loss of tear film homeostasis.', 'Definición y clasificación consensuada de ojo seco basada en pérdida de homeostasis lagrimal.', 'Classify DED into aqueous-deficient, evaporative and mixed mechanisms; emphasise homeostasis and symptoms/signs.', 'Clasificar ojo seco en acuodeficiente, evaporativo y mixto; enfatizar homeostasis, síntomas y signos.', 'Foundational ocular surface reference relevant to corneal keratitis in dry eye.', 'Use citation and own summary.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, doi, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('TFOS DEWS II Management and Therapy Report', 'Tear Film & Ocular Surface Society', 'International', 'consensus_statement', 'cornea', 2017, 'DEWS II', 'https://pubmed.ncbi.nlm.nih.gov/28736343/', '10.1016/j.jtos.2017.05.006', 'Jones L et al. TFOS DEWS II Management and Therapy Report. Ocul Surf. 2017.', 'Consensus staged management of dry eye disease and ocular surface inflammation.', 'Manejo escalonado consensuado del ojo seco y la inflamación de superficie ocular.', 'Escalate therapy by severity and mechanism; address lid disease, inflammation and tear film support.', 'Escalar tratamiento por gravedad/mecanismo; tratar párpados, inflamación y soporte lagrimal.', 'Useful for corneal surface disease protocols.', 'Use citation and own summary.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Global Consensus on Keratoconus and Ectatic Diseases', 'International expert panel', 'International', 'consensus_statement', 'cornea', 2015, 'Global consensus', 'https://pubmed.ncbi.nlm.nih.gov/25738235/', 'Global consensus on keratoconus and ectatic diseases. Cornea. 2015.', 'Consensus definitions and management principles for keratoconus and ectatic diseases.', 'Consenso sobre definiciones y manejo de queratocono y ectasias.', 'Tomography is central; progression drives cross-linking decisions; visual rehabilitation must be individualised.', 'La tomografía es central; la progresión guía el cross-linking; rehabilitación visual individualizada.', 'Supports ectasia database entries alongside AAO PPP.', 'Use PubMed metadata and own summary.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_guidelines (title, organization, country_region, source_type, subspecialty, publication_year, version, url, citation, summary_en, summary_es, key_recommendations_en, key_recommendations_es, notes_on_use, copyright_notes, status, is_active, metadata) values ('Global Consensus on Limbal Stem Cell Deficiency', 'Cornea / ocular surface expert consensus', 'International', 'consensus_statement', 'cornea', 2019, 'Consensus', 'https://pubmed.ncbi.nlm.nih.gov/30946932/', 'Global consensus on definition, classification, diagnosis and staging of limbal stem cell deficiency.', 'Consensus defining and staging limbal stem cell deficiency.', 'Consenso de definición, clasificación, diagnóstico y estadificación de deficiencia de células madre limbares.', 'Use clinical signs, extent of limbal involvement and central corneal involvement to stage disease.', 'Usar signos clínicos, extensión limbar y afectación central para estadificar.', 'Key source for LSCD and chemical burn sequelae.', 'Use citation and own summary.', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_classifications (name, acronym, description_en, description_es, clinical_use_en, clinical_use_es, original_source, references_json, subspecialty, status, is_active, metadata) values ('Amsler-Krumeich keratoconus classification', 'AK', 'Traditional keratoconus grading based on keratometry, myopia/astigmatism, corneal transparency and thickness.', 'Clasificación tradicional de queratocono según queratometría, miopía/astigmatismo, transparencia y grosor.', 'Historical severity grading; less precise than tomography-based systems but still widely recognised.', 'Graduación histórica; menos precisa que sistemas tomográficos pero ampliamente reconocida.', 'Amsler/Krumeich keratoconus grading', '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}, {"title": "Global consensus on keratoconus and ectatic diseases", "url": "https://pubmed.ncbi.nlm.nih.gov/25738235/"}]'::jsonb, 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_classifications (name, acronym, description_en, description_es, clinical_use_en, clinical_use_es, original_source, references_json, subspecialty, status, is_active, metadata) values ('ABCD keratoconus staging', 'ABCD', 'Tomography-based staging using anterior radius, posterior radius, thinnest pachymetry and best-corrected visual acuity.', 'Estadificación tomográfica con radio anterior, radio posterior, paquimetría mínima y AV corregida.', 'Modern staging and progression monitoring in keratoconus.', 'Estadificación moderna y seguimiento de progresión.', 'Belin ABCD classification', '[{"title": "Belin ABCD keratoconus classification and staging evidence", "url": "https://pubmed.ncbi.nlm.nih.gov/29753871/"}, {"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}]'::jsonb, 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_classifications (name, acronym, description_en, description_es, clinical_use_en, clinical_use_es, original_source, references_json, subspecialty, status, is_active, metadata) values ('IC3D classification of corneal dystrophies', 'IC3D', 'International classification of corneal dystrophies integrating clinical, genetic and pathological evidence.', 'Clasificación internacional de distrofias corneales que integra clínica, genética y patología.', 'Standardised nomenclature for epithelial, stromal and endothelial dystrophies.', 'Nomenclatura estandarizada de distrofias epiteliales, estromales y endoteliales.', 'IC3D Classification Edition 2', '[{"title": "IC3D Classification of Corneal Dystrophies Edition 2", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4122549/"}]'::jsonb, 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_classifications (name, acronym, description_en, description_es, clinical_use_en, clinical_use_es, original_source, references_json, subspecialty, status, is_active, metadata) values ('Mackie classification of neurotrophic keratitis', 'Mackie NK', 'Three-stage classification: stage 1 epithelial changes, stage 2 persistent epithelial defect, stage 3 corneal ulcer/melt/perforation.', 'Tres estadios: 1 cambios epiteliales, 2 defecto epitelial persistente, 3 úlcera/melting/perforación.', 'Clinical severity staging and treatment escalation for neurotrophic keratitis.', 'Estadificación de gravedad y escalada terapéutica en queratitis neurotrófica.', 'Mackie neurotrophic keratitis classification', '[{"title": "EMA Oxervate EPAR", "url": "https://www.ema.europa.eu/en/medicines/human/EPAR/oxervate"}, {"title": "Neurotrophic keratopathy clinical presentation and cenegermin outcomes review", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8938625/"}]'::jsonb, 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_classifications (name, acronym, description_en, description_es, clinical_use_en, clinical_use_es, original_source, references_json, subspecialty, status, is_active, metadata) values ('Roper-Hall classification of ocular chemical burns', 'Roper-Hall', 'Grades chemical injury based on corneal haze and limbal ischemia.', 'Grados de quemadura química según opacidad corneal e isquemia limbar.', 'Prognosis and initial severity assessment after chemical injury.', 'Pronóstico y evaluación inicial de severidad tras lesión química.', 'Roper-Hall ocular burn classification', '[{"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}, {"title": "Global consensus on definition, classification, diagnosis and staging of limbal stem cell deficiency", "url": "https://pubmed.ncbi.nlm.nih.gov/30946932/"}]'::jsonb, 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
