insert into public.oph_devices (name, manufacturer, device_category, description_en, intended_use_en, indications_en, limitations_en, safety_notes_en, regulatory_status, references_json, description_es, intended_use_es, indications_es, limitations_es, safety_notes_es, subspecialty, status, is_active, metadata) values ('Keratoplasty surgical instrument set', 'Multiple manufacturers', 'instrumentation', 'Trephines, punches, forceps, injectors and endothelial graft preparation/insertion instruments.', 'PK, DALK, DMEK, DSAEK and ocular surface surgery.', 'Corneal transplantation and lamellar keratoplasty procedures.', 'Surgeon-dependent; device choices vary.', 'Sterility, tissue handling and intraoperative complication management.', 'Device-specific.', '[{"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'Trephines, punches, forceps, injectors and endothelial graft preparation/insertion instruments.', 'PK, DALK, DMEK, DSAEK and ocular surface surgery.', 'Corneal transplantation and lamellar keratoplasty procedures.', 'Surgeon-dependent; device choices vary.', 'Sterility, tissue handling and intraoperative complication management.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_devices (name, manufacturer, device_category, description_en, intended_use_en, indications_en, limitations_en, safety_notes_en, regulatory_status, references_json, description_es, intended_use_es, indications_es, limitations_es, safety_notes_es, subspecialty, status, is_active, metadata) values ('Anterior chamber air/gas tamponade tools for endothelial keratoplasty', 'Multiple manufacturers', 'surgical', 'Air/gas injection systems used for graft apposition in endothelial keratoplasty.', 'DMEK/DSAEK graft attachment.', 'Endothelial keratoplasty surgery.', 'Risk of pupillary block or pressure rise if not managed.', 'IOP monitoring and iridotomy/positioning protocols as needed.', 'Procedure/device-specific.', '[{"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}]'::jsonb, 'Air/gas injection systems used for graft apposition in endothelial keratoplasty.', 'DMEK/DSAEK graft attachment.', 'Endothelial keratoplasty surgery.', 'Risk of pupillary block or pressure rise if not managed.', 'IOP monitoring and iridotomy/positioning protocols as needed.', 'cornea', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (slug, title_en, title_es, protocol_type, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, references_json, subspecialty, evidence_level, status, is_active, metadata) values ('cornea_keratoconus_workup_progression', 'Keratoconus work-up and progression pathway', 'Ruta de estudio y progresión del queratocono', 'diagnostic', 'Cornea clinic / refractive screening', 'Identify keratoconus, document progression and select appropriate visual rehabilitation or cross-linking pathway.', 'Identificar queratocono, documentar progresión y seleccionar rehabilitación o cross-linking.', 'Irregular astigmatism, suspected ectasia, progressive myopia/astigmatism or abnormal topography.', 'Astigmatismo irregular, sospecha de ectasia, progresión refractiva o topografía anómala.', '1. History including allergy/eye rubbing/family history. 2. Refraction and BCVA. 3. Slit-lamp signs. 4. Topography/tomography/pachymetry. 5. Compare prior studies for progression. 6. Treat allergy/eye rubbing. 7. Choose spectacles/contact lenses/CXL/surgical options.', '1. Historia. 2. Refracción y AV. 3. Lámpara. 4. Topografía/tomografía. 5. Comparar progresión. 6. Control alergia/frotamiento. 7. Elegir tratamiento.', 'Corneal tomography, pachymetry, epithelial mapping, refraction and visual acuity; biomechanical assessment if available.', 'Tomografía, paquimetría, mapa epitelial, refracción y AV; biomecánica si disponible.', 'Stable mild disease: optical correction and monitoring. Progressive disease: cross-linking if safety criteria met. Advanced irregularity: specialty lenses, ICRS or keratoplasty in selected cases.', 'Estable leve: corrección y seguimiento. Progresivo: cross-linking si cumple criterios. Avanzado: lentes especiales, segmentos o queratoplastia.', 'Young/progressive patients require shorter intervals; stable adults may be monitored less frequently.', 'Jóvenes/progresivos con intervalos cortos; adultos estables menos frecuentes.', 'Documented progression, contact lens failure, apical scarring, hydrops or severe thinning.', 'Progresión, intolerancia a lentes, cicatriz, hidrops o adelgazamiento severo.', 'Rapid progression in adolescents, hydrops, very thin cornea.', 'Progresión rápida en adolescentes, hidrops, córnea muy fina.', 'Educational protocol only; CXL eligibility depends on device/product label and clinician judgement.', 'Protocolo educativo; elegibilidad CXL depende de ficha/dispositivo y juicio clínico.', '[{"title": "AAO Corneal Ectasia Preferred Practice Pattern (2024 PDF)", "url": "https://www.aao.org/Assets/c36981e3-79e1-4e9f-96c8-8e2d96dc2a7b/638544878396730000/corneal-ectasia-ppp-6-18-24-pdf"}, {"title": "Global consensus on keratoconus and ectatic diseases", "url": "https://pubmed.ncbi.nlm.nih.gov/25738235/"}]'::jsonb, 'cornea', 'expert_consensus', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (slug, title_en, title_es, protocol_type, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, references_json, subspecialty, evidence_level, status, is_active, metadata) values ('cornea_microbiological_keratitis_emergency', 'Microbial keratitis emergency pathway', 'Ruta urgente de queratitis microbiana', 'emergency', 'Emergency eye clinic / cornea service', 'Recognise sight-threatening keratitis, obtain appropriate microbiology and start urgent therapy.', 'Reconocer queratitis grave, obtener microbiología adecuada e iniciar tratamiento urgente.', 'Corneal epithelial defect with stromal infiltrate, pain, photophobia or suspected infection.', 'Defecto epitelial con infiltrado, dolor, fotofobia o sospecha infecciosa.', '1. Assess vision, pain, contact lens history and risk factors. 2. Document size, location, depth, thinning and AC reaction. 3. Culture/scrape if central, large, severe, atypical or nonresponding. 4. Start intensive antimicrobial therapy. 5. Review frequently until improvement. 6. Adjust based on organism and response.', '1. AV, dolor y riesgos. 2. Documentar tamaño/localización/profundidad/adelgazamiento/CA. 3. Cultivo si central/grande/severa/atípica/no responde. 4. Antimicrobianos intensivos. 5. Revisión frecuente. 6. Ajustar.', 'Slit-lamp photography, fluorescein staining, corneal scraping/culture, confocal/PCR for atypical organisms when available.', 'Fotografía, fluoresceína, raspado/cultivo, confocal/PCR si atípica.', 'Broad-spectrum topical antibiotic for bacterial suspicion; organism-specific antifungal/anti-amoebic/antiviral strategy when suspected or confirmed.', 'Antibiótico tópico amplio si bacteriana; estrategia antifúngica/antiamebiana/antiviral según sospecha o confirmación.', 'Daily or more frequent early review for severe ulcers.', 'Revisión diaria o más frecuente inicialmente si severa.', 'Worsening infiltrate, melt, perforation, hypopyon, no response or atypical features.', 'Empeora, melting, perforación, hipopion, no respuesta o atípica.', 'Central ulcer, contact lens Pseudomonas risk, Acanthamoeba pain, fungal features, perforation.', 'Úlcera central, riesgo Pseudomonas, dolor Acanthamoeba, rasgos fúngicos, perforación.', 'Sight-threatening infection; urgent specialist care required.', 'Infección amenazante para la visión; requiere atención urgente especializada.', '[{"title": "College of Optometrists Clinical Management Guideline: Microbial keratitis bacterial/fungal", "url": "https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_bacterial_fungal"}, {"title": "College of Optometrists Clinical Management Guideline: Acanthamoeba keratitis", "url": "https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/microbialkeratitis_acanthamoebasp"}]'::jsonb, 'cornea', 'expert_consensus', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (slug, title_en, title_es, protocol_type, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, references_json, subspecialty, evidence_level, status, is_active, metadata) values ('cornea_neurotrophic_keratitis_pathway', 'Neurotrophic keratitis staging and management pathway', 'Ruta de estadificación y manejo de queratitis neurotrófica', 'therapeutic', 'Cornea / ocular surface clinic', 'Stage NK, protect the ocular surface and escalate therapy to prevent melt/perforation.', 'Estadificar QN, proteger la superficie y escalar para prevenir melting/perforación.', 'Reduced corneal sensation with epithelial disease, persistent epithelial defect or neurotrophic ulcer.', 'Sensibilidad corneal reducida con enfermedad epitelial, defecto persistente o úlcera neurotrófica.', '1. Measure/document corneal sensation. 2. Identify cause and toxic medications. 3. Stage epithelial disease. 4. Stop preservatives/toxic drops where possible. 5. Lubricate and protect. 6. Escalate to bandage/scleral lens, amniotic membrane, cenegermin or tarsorrhaphy depending stage. 7. Monitor closely.', '1. Medir sensibilidad. 2. Identificar causa/tóxicos. 3. Estadificar. 4. Retirar conservantes/tóxicos. 5. Lubricar/proteger. 6. Escalar. 7. Seguimiento estrecho.', 'Corneal sensitivity, staining, AS-OCT for thinning, infection exclusion, assessment of eyelid/exposure.', 'Sensibilidad, tinción, OCT-SA para adelgazamiento, excluir infección, párpados/exposición.', 'Stage 1: lubrication and risk control. Stage 2: epithelial healing support. Stage 3: ulcer/melt protection, biological therapy/surgery and emergency measures.', 'Estadio 1: lubricación/control. Estadio 2: soporte de cicatrización. Estadio 3: protección, terapia biológica/cirugía.', 'Frequent until epithelial closure; long-term recurrence prevention.', 'Frecuente hasta cierre epitelial; prevención a largo plazo.', 'Persistent epithelial defect, ulcer, stromal thinning, infection or perforation risk.', 'Defecto persistente, úlcera, adelgazamiento, infección o riesgo perforación.', 'Little pain despite severe defect, melt, perforation.', 'Poco dolor pese a defecto severo, melting, perforación.', 'Moderate/severe disease may require treatments such as cenegermin where approved.', 'Enfermedad moderada/severa puede requerir cenegermina donde esté aprobada.', '[{"title": "EMA Oxervate EPAR", "url": "https://www.ema.europa.eu/en/medicines/human/EPAR/oxervate"}, {"title": "Neurotrophic keratopathy clinical presentation and cenegermin outcomes review", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8938625/"}]'::jsonb, 'cornea', 'expert_consensus', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (slug, title_en, title_es, protocol_type, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, references_json, subspecialty, evidence_level, status, is_active, metadata) values ('cornea_chemical_burn_acute_protocol', 'Acute chemical ocular burn protocol', 'Protocolo agudo de quemadura química ocular', 'emergency', 'Emergency department / ophthalmology emergency', 'Prioritise immediate irrigation, pH normalisation and early severity assessment.', 'Priorizar irrigación inmediata, normalizar pH y evaluar severidad temprana.', 'Known or suspected chemical exposure to ocular surface.', 'Exposición química ocular conocida o sospechada.', '1. Irrigate immediately before detailed history. 2. Remove particulate matter and evert lids. 3. Check pH repeatedly until neutral. 4. Assess visual acuity, limbal ischemia, corneal clarity, epithelial defect and IOP. 5. Grade severity. 6. Initiate specialist anti-inflammatory, epithelial support and IOP management. 7. Plan close follow-up/reconstruction if needed.', '1. Irrigar de inmediato. 2. Retirar partículas/evertir. 3. pH hasta neutral. 4. AV, isquemia limbar, claridad, defecto, PIO. 5. Grado. 6. Manejo especializado. 7. Seguimiento/reconstrucción.', 'pH, slit lamp, fluorescein, IOP, limbal/conjunctival ischemia assessment.', 'pH, lámpara, fluoresceína, PIO, isquemia limbar/conjuntival.', 'Immediate irrigation dominates; subsequent therapy based on severity and epithelial/limbal involvement.', 'La irrigación inmediata es prioritaria; tratamiento posterior según severidad.', 'Severe burns require very close early follow-up.', 'Quemaduras severas requieren seguimiento muy estrecho.', 'Limbal ischemia, corneal haze, persistent defect, high IOP, melt.', 'Isquemia limbar, haze, defecto persistente, PIO alta, melting.', 'Alkali burn, limbal ischemia, corneal opacification, high IOP.', 'Quemadura alcalina, isquemia limbar, opacidad, PIO alta.', 'This is an ophthalmic emergency; irrigation must not be delayed.', 'Urgencia oftalmológica; no retrasar irrigación.', '[{"title": "AAO Cornea/External Disease Summary Benchmarks", "url": "https://www.aao.org/education/summary-benchmark-detail/cornea-external-disease-summary-benchmarks-2020"}, {"title": "Global consensus on definition, classification, diagnosis and staging of limbal stem cell deficiency", "url": "https://pubmed.ncbi.nlm.nih.gov/30946932/"}]'::jsonb, 'cornea', 'expert_consensus', 'pending_review', false, '{"block": "cornea_v1", "review_required": true}'::jsonb) on conflict do nothing;
