insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Dry eye disease', 'Enfermedad de ojo seco', 'ocular-surface-dry-eye-disease', 'ocular_surface', 'Multifactorial ocular surface disease characterized by loss of tear film homeostasis, symptoms and tear instability, often with hyperosmolarity, inflammation, surface damage and neurosensory abnormalities.', 'Enfermedad multifactorial de la superficie ocular caracterizada por pérdida de homeostasis de la película lagrimal, síntomas e inestabilidad lagrimal, a menudo con hiperosmolaridad, inflamación, daño de superficie y alteraciones neurosensoriales.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Age, female sex, autoimmune disease, MGD, screen use, medications, ocular surgery, contact lenses, low humidity.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Burning, foreign body sensation, fluctuating vision, photophobia, staining, low TBUT, reduced Schirmer or hyperosmolarity depending on subtype.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Symptom questionnaire, slit-lamp exam, tear break-up time, ocular surface staining, lid/MGD assessment, Schirmer when aqueous deficiency suspected, targeted testing when severe or discordant.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Education, environmental measures, lubricants, lid management, anti-inflammatory therapy when indicated, tear conservation, treatment of MGD, serum tears/scleral lenses for severe disease.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Severe pain, unilateral marked redness, corneal ulcer, significant vision loss, cicatrization, suspicion of autoimmune disease or infection.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'guideline', 'TFOS DEWS II and AAO Dry Eye PPP aligned educational monograph.', '[{"key": "TFOS_DEWS_II", "url": "https://www.tfosdewsreport.org/"}, {"key": "TFOS_DEWS_II_MANAGEMENT", "url": "https://www.tfosdewsreport.org/report-management_and_therapy/147_36/en/"}, {"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Evaporative dry eye', 'Ojo seco evaporativo', 'ocular-surface-evaporative-dry-eye', 'ocular_surface', 'Dry eye subtype dominated by excessive evaporation, most commonly related to meibomian gland dysfunction.', 'Subtipo de ojo seco dominado por evaporación excesiva, habitualmente relacionado con disfunción de glándulas de Meibomio.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'MGD, rosacea, blepharitis, aging, screen use, isotretinoin exposure, contact lenses.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Short TBUT, lid margin changes, abnormal meibum, telangiectasia, evaporative symptoms and variable staining.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid margin examination, meibum expressibility/quality, TBUT, meibography when available, ocular surface staining.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid hygiene, warm compresses, lipid-containing lubricants, anti-inflammatory therapy, oral tetracyclines/macrolides in selected rosacea/MGD, thermal pulsation/IPL where appropriate.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Severe ocular surface staining, pain out of proportion, suspicion of infection, cicatrization.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'guideline', 'Defined under TFOS DEWS II and TFOS MGD framework.', '[{"key": "TFOS_DEWS_II", "url": "https://www.tfosdewsreport.org/"}, {"key": "TFOS_MGD_WORKSHOP", "url": "https://www.tearfilm.org/reports-tfos_international_workshop_on_mgd/7250_7239/eng/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Aqueous-deficient dry eye', 'Ojo seco acuodeficiente', 'ocular-surface-aqueous-deficient-dry-eye', 'ocular_surface', 'Dry eye subtype caused by insufficient lacrimal aqueous secretion, including Sjögren and non-Sjögren forms.', 'Subtipo de ojo seco por secreción acuosa lagrimal insuficiente, incluyendo formas Sjögren y no Sjögren.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Sjögren disease, lacrimal gland disease, aging, systemic medications, graft-versus-host disease, radiation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Low tear meniscus, reduced Schirmer, conjunctival/corneal staining, filamentary keratitis in severe cases.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Schirmer testing, ocular staining, review systemic symptoms and medications, Sjögren work-up when indicated.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Frequent lubricants, anti-inflammatory therapy, punctal occlusion after inflammation control, secretagogues/systemic care for Sjögren, serum tears/scleral lenses in severe disease.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Severe keratitis, filamentary keratitis, corneal melt risk, systemic autoimmune symptoms.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'guideline', 'TFOS/AAO dry eye framework and EULAR Sjögren guidance.', '[{"key": "TFOS_DEWS_II", "url": "https://www.tfosdewsreport.org/"}, {"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}, {"key": "EULAR_SJOGREN", "url": "https://ard.bmj.com/content/79/1/3"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Meibomian gland dysfunction', 'Disfunción de glándulas de Meibomio', 'ocular-surface-meibomian-gland-dysfunction', 'ocular_surface', 'Chronic diffuse abnormality of meibomian glands, commonly with terminal duct obstruction and/or qualitative or quantitative changes in glandular secretion.', 'Alteración crónica y difusa de las glándulas de Meibomio, con obstrucción ductal terminal y/o cambios cualitativos o cuantitativos de la secreción.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Age, rosacea, androgen deficiency, contact lenses, isotretinoin, chronic blepharitis.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid margin telangiectasia, capped glands, poor expressibility, turbid/thick meibum, short TBUT, ocular irritation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid margin inspection, gland expression, TBUT, staining, meibography and interferometry if available.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Education, lid hygiene, heat, gland expression, lipid lubricants, anti-inflammatory therapy, oral doxycycline/azithromycin in selected cases, thermal pulsation/IPL in selected cases.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Marked unilateral lid changes, lash loss or lid margin distortion suggesting malignancy; severe keratitis.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'expert_consensus', 'TFOS International Workshop on MGD framework.', '[{"key": "TFOS_MGD_WORKSHOP", "url": "https://www.tearfilm.org/reports-tfos_international_workshop_on_mgd/7250_7239/eng/"}, {"key": "TFOS_DEWS_II_MANAGEMENT", "url": "https://www.tfosdewsreport.org/report-management_and_therapy/147_36/en/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Anterior blepharitis', 'Blefaritis anterior', 'ocular-surface-anterior-blepharitis', 'ocular_surface', 'Inflammation of the anterior lid margin involving lashes and follicles, often seborrheic, staphylococcal or mixed.', 'Inflamación del margen palpebral anterior que afecta pestañas y folículos, con frecuencia seborreica, estafilocócica o mixta.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Seborrheic dermatitis, rosacea, chronic lid colonization, poor lid hygiene.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Crusting, collarettes, lash debris, itching, burning, lid margin erythema.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Slit lamp lid margin exam, lash/collarette assessment, evaluate Demodex when cylindrical dandruff present.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid hygiene, topical antibiotics in selected bacterial flares, anti-inflammatory therapy when significant inflammation, treat associated Demodex/rosacea.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Unilateral chronic lesion, lash loss, ulceration, notching or non-resolving inflammation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'educational_reference', 'Ocular surface and external disease educational synthesis.', '[{"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}, {"key": "TFOS_MGD_WORKSHOP", "url": "https://www.tearfilm.org/reports-tfos_international_workshop_on_mgd/7250_7239/eng/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Demodex blepharitis', 'Blefaritis por Demodex', 'ocular-surface-demodex-blepharitis', 'ocular_surface', 'Blepharitis associated with Demodex mites, clinically suggested by cylindrical dandruff/collarettes at lash bases.', 'Blefaritis asociada a ácaros Demodex, sugerida clínicamente por caspa cilíndrica/collarettes en la base de las pestañas.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Age, rosacea, chronic blepharitis, immunosuppression.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Collarettes, itching, lid margin inflammation, recurrent chalazia, ocular irritation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Slit lamp identification of collarettes; lash epilation/microscopy only if needed.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid hygiene and targeted anti-Demodex therapy according to local availability; avoid overdiagnosis and treat comorbid MGD/DED.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Severe unilateral lid abnormality or suspicion of masquerade lesion.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'educational_reference', 'Included as common ocular surface blepharitis phenotype requiring local treatment availability check.', '[{"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Ocular rosacea', 'Rosácea ocular', 'ocular-surface-ocular-rosacea', 'ocular_surface', 'Ocular involvement of rosacea with lid margin inflammation, MGD, recurrent chalazia and keratitis in some patients.', 'Afectación ocular de la rosácea con inflamación del margen palpebral, DGM, chalaziones recurrentes y queratitis en algunos pacientes.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Cutaneous rosacea, fair skin phenotype, MGD, chronic inflammation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid telangiectasia, posterior blepharitis, recurrent chalazia, conjunctival hyperemia, peripheral keratitis or phlyctenules.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Ocular surface/lid exam and dermatologic history; assess cornea carefully.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Lid hygiene, lubricants, anti-inflammatory therapy, oral tetracyclines/macrolides in selected moderate-severe cases, dermatology collaboration.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Peripheral ulcerative keratitis, corneal thinning, severe photophobia or reduced vision.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'educational_reference', 'Consensus-based ocular surface rosacea educational monograph.', '[{"key": "TFOS_MGD_WORKSHOP", "url": "https://www.tearfilm.org/reports-tfos_international_workshop_on_mgd/7250_7239/eng/"}, {"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
