nd protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Pain, photophobia, decreased vision, corneal involvement or unilateral purulent discharge.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'expert_consensus', 'EAACI ocular allergy framework.', '[{"key": "EAACI_OCULAR_ALLERGY", "url": "https://eaaci.org/guidelines-position-papers/management-of-ocular-allergy/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_pathologies (name_en, name_es, slug, subspecialty, definition_en, definition_es, epidemiology_en, epidemiology_es, risk_factors_en, risk_factors_es, clinical_features_en, clinical_features_es, differential_diagnosis_en, differential_diagnosis_es, diagnostic_workup_en, diagnostic_workup_es, treatment_overview_en, treatment_overview_es, follow_up_en, follow_up_es, red_flags_en, red_flags_es, evidence_level, source_summary, references_json, status, is_active, metadata) values ('Perennial allergic conjunctivitis', 'Conjuntivitis alérgica perenne', 'ocular-surface-perennial-allergic-conjunctivitis', 'ocular_surface', 'IgE-mediated ocular allergy due to perennial allergens such as dust mite, animal dander or molds.', 'Alergia ocular mediada por IgE por alérgenos perennes como ácaros, epitelios animales o mohos.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Atopy, indoor allergen exposure, allergic rhinitis/asthma.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Chronic itching, redness, tearing and mild papillary response.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Clinical diagnosis and allergy history; consider allergy referral if severe/persistent.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Avoidance, artificial tears, dual-action antihistamine/mast-cell stabilizers, environmental control.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Educational summary; requires local epidemiology and protocol adaptation.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'Corneal disease, severe papillae, shield ulcer, pain or vision loss.', 'Resumen educativo pendiente de revisión editorial/KOL para redacción final en español.', 'expert_consensus', 'EAACI ocular allergy framework.', '[{"key": "EAACI_OCULAR_ALLERGY", "url": "https://eaaci.org/guidelines-position-papers/management-of-ocular-allergy/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "review_status": "pending_kol_review", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
