insert into public.oph_protocols (title_en, title_es, slug, subspecialty, protocol_type, target_audience, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, exclusion_criteria_en, exclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, evidence_level, references_json, status, is_active, metadata) values ('Dry Eye Disease Diagnostic and Therapeutic Pathway', 'Protocolo diagnóstico-terapéutico de ojo seco', 'ocular-surface-protocol-dry-eye-disease', 'ocular_surface', 'diagnostic', 'ophthalmologists', 'outpatient ocular surface / cornea clinic', 'Provide an educational workflow to phenotype and manage dry eye disease safely.', 'Flujo educativo para fenotipar y manejar ojo seco con seguridad.', 'Patients with symptoms/signs compatible with the pathway.', 'Pacientes con síntomas/signos compatibles con el protocolo.', 'This educational pathway does not apply to emergency infection, trauma or cases needing immediate specialist care.', 'No aplica a infección urgente, trauma o necesidad inmediata de especialista.', '1) Confirm symptoms and impact. 2) Assess signs: TBUT, staining, lid margin, tear meniscus. 3) Phenotype evaporative/aqueous/mixed/neurosensory. 4) Identify red flags. 5) Stage management and follow response.', 'Pendiente de revisión editorial/KOL.', 'Slit lamp exam, staining, TBUT, lid assessment and targeted testing depending on phenotype.', 'Lámpara de hendidura, tinción, TBUT, evaluación palpebral y pruebas dirigidas según fenotipo.', 'Education/environment -> lubricants -> lid/MGD therapy -> anti-inflammatory therapy when indicated -> tear conservation/serum/scleral lenses for severe disease.', 'Pendiente de adaptación editorial/KOL.', 'Follow-up based on severity, therapy risk and corneal involvement.', 'Seguimiento según severidad, riesgo terapéutico y afectación corneal.', 'Escalate if severe, refractory, vision-threatening, cicatrizing or steroid-dependent.', 'Escalar si severo, refractario, amenaza visual, cicatrizante o dependiente de esteroides.', 'Pain, photophobia, decreased vision, epithelial defect, ulcer, cicatrization, severe unilateral signs.', 'Dolor, fotofobia, pérdida visual, defecto epitelial, ulceración, cicatrización o sospecha infecciosa.', 'Educational protocol only; not individual medical advice. Verify local medicines and guidelines.', 'Protocolo educativo; no es consejo médico individual. Verificar fármacos y guías locales.', 'expert_consensus', '[{"key": "TFOS_DEWS_II", "url": "https://www.tfosdewsreport.org/"}, {"key": "TFOS_DEWS_II_MANAGEMENT", "url": "https://www.tfosdewsreport.org/report-management_and_therapy/147_36/en/"}, {"key": "AAO_DRY_EYE_PPP_2023", "url": "https://www.aao.org/education/preferred-practice-pattern/dry-eye-syndrome-ppp-2023"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (title_en, title_es, slug, subspecialty, protocol_type, target_audience, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, exclusion_criteria_en, exclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, evidence_level, references_json, status, is_active, metadata) values ('Meibomian Gland Dysfunction Management Pathway', 'Protocolo de manejo de disfunción de glándulas de Meibomio', 'ocular-surface-protocol-mgd-management', 'ocular_surface', 'therapeutic', 'ophthalmologists', 'outpatient ocular surface / cornea clinic', 'Structure educational management of MGD and evaporative dry eye.', 'Estructurar manejo educativo de DGM y ojo seco evaporativo.', 'Patients with symptoms/signs compatible with the pathway.', 'Pacientes con síntomas/signos compatibles con el protocolo.', 'This educational pathway does not apply to emergency infection, trauma or cases needing immediate specialist care.', 'No aplica a infección urgente, trauma o necesidad inmediata de especialista.', '1) Grade lid margin and meibum. 2) Treat hygiene/heat. 3) Address inflammation/rosacea. 4) Consider device-based therapy in selected cases. 5) Monitor symptoms, TBUT, glands and cornea.', 'Pendiente de revisión editorial/KOL.', 'Slit lamp exam, staining, TBUT, lid assessment and targeted testing depending on phenotype.', 'Lámpara de hendidura, tinción, TBUT, evaluación palpebral y pruebas dirigidas según fenotipo.', 'Lid hygiene + heat -> lubricants lipid -> anti-inflammatory/antibiotic strategies when indicated -> thermal pulsation/IPL in selected cases.', 'Pendiente de adaptación editorial/KOL.', 'Follow-up based on severity, therapy risk and corneal involvement.', 'Seguimiento según severidad, riesgo terapéutico y afectación corneal.', 'Escalate if severe, refractory, vision-threatening, cicatrizing or steroid-dependent.', 'Escalar si severo, refractario, amenaza visual, cicatrizante o dependiente de esteroides.', 'Unilateral lid destruction/lash loss, corneal thinning, infectious keratitis suspicion.', 'Dolor, fotofobia, pérdida visual, defecto epitelial, ulceración, cicatrización o sospecha infecciosa.', 'Educational protocol only; not individual medical advice. Verify local medicines and guidelines.', 'Protocolo educativo; no es consejo médico individual. Verificar fármacos y guías locales.', 'expert_consensus', '[{"key": "TFOS_MGD_WORKSHOP", "url": "https://www.tearfilm.org/reports-tfos_international_workshop_on_mgd/7250_7239/eng/"}, {"key": "TFOS_DEWS_II_MANAGEMENT", "url": "https://www.tfosdewsreport.org/report-management_and_therapy/147_36/en/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (title_en, title_es, slug, subspecialty, protocol_type, target_audience, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, exclusion_criteria_en, exclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, evidence_level, references_json, status, is_active, metadata) values ('Ocular Allergy Severity-Based Pathway', 'Protocolo por severidad de alergia ocular', 'ocular-surface-protocol-ocular-allergy', 'ocular_surface', 'therapeutic', 'ophthalmologists', 'outpatient ocular surface / cornea clinic', 'Differentiate simple allergic conjunctivitis from VKC/AKC/GPC and detect corneal red flags.', 'Diferenciar alergia simple de VKC/AKC/GPC y detectar red flags corneales.', 'Patients with symptoms/signs compatible with the pathway.', 'Pacientes con síntomas/signos compatibles con el protocolo.', 'This educational pathway does not apply to emergency infection, trauma or cases needing immediate specialist care.', 'No aplica a infección urgente, trauma o necesidad inmediata de especialista.', '1) Classify SAC/PAC/VKC/AKC/GPC. 2) Evert lids and assess cornea. 3) Use anti-allergy therapy by severity. 4) Reserve steroids/immunomodulators for supervised severe disease. 5) Monitor IOP if steroids used.', 'Pendiente de revisión editorial/KOL.', 'Slit lamp exam, staining, TBUT, lid assessment and targeted testing depending on phenotype.', 'Lámpara de hendidura, tinción, TBUT, evaluación palpebral y pruebas dirigidas según fenotipo.', 'Avoidance/lubricants -> antihistamine/mast-cell stabilizer -> short supervised steroid if severe -> immunomodulator/specialist care for VKC/AKC.', 'Pendiente de adaptación editorial/KOL.', 'Follow-up based on severity, therapy risk and corneal involvement.', 'Seguimiento según severidad, riesgo terapéutico y afectación corneal.', 'Escalate if severe, refractory, vision-threatening, cicatrizing or steroid-dependent.', 'Escalar si severo, refractario, amenaza visual, cicatrizante o dependiente de esteroides.', 'Photophobia, shield ulcer, reduced vision, severe papillae, steroid complications.', 'Dolor, fotofobia, pérdida visual, defecto epitelial, ulceración, cicatrización o sospecha infecciosa.', 'Educational protocol only; not individual medical advice. Verify local medicines and guidelines.', 'Protocolo educativo; no es consejo médico individual. Verificar fármacos y guías locales.', 'expert_consensus', '[{"key": "EAACI_OCULAR_ALLERGY", "url": "https://eaaci.org/guidelines-position-papers/management-of-ocular-allergy/"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
insert into public.oph_protocols (title_en, title_es, slug, subspecialty, protocol_type, target_audience, clinical_setting, objective_en, objective_es, inclusion_criteria_en, inclusion_criteria_es, exclusion_criteria_en, exclusion_criteria_es, step_by_step_en, step_by_step_es, investigations_en, investigations_es, treatment_algorithm_en, treatment_algorithm_es, follow_up_en, follow_up_es, escalation_criteria_en, escalation_criteria_es, red_flags_en, red_flags_es, patient_safety_notes_en, patient_safety_notes_es, evidence_level, references_json, status, is_active, metadata) values ('Cicatrizing Conjunctivitis Red-Flag Pathway', 'Protocolo de red flags en conjuntivitis cicatrizante', 'ocular-surface-protocol-cicatrizing-conjunctivitis', 'ocular_surface', 'diagnostic', 'ophthalmologists', 'outpatient ocular surface / cornea clinic', 'Identify ocular MMP, SJS/TEN and other cicatrizing causes early.', 'Identificar precozmente PMM ocular, SJS/TEN y otras causas cicatrizantes.', 'Patients with symptoms/signs compatible with the pathway.', 'Pacientes con síntomas/signos compatibles con el protocolo.', 'This educational pathway does not apply to emergency infection, trauma or cases needing immediate specialist care.', 'No aplica a infección urgente, trauma o necesidad inmediata de especialista.', '1) Document fornix depth, symblepharon, keratinization and trichiasis. 2) Stop toxic medications when relevant. 3) Consider biopsy/systemic assessment. 4) Refer to ocular surface/immunology specialist. 5) Avoid elective surface surgery in active inflammation.', 'Pendiente de revisión editorial/KOL.', 'Slit lamp exam, staining, TBUT, lid assessment and targeted testing depending on phenotype.', 'Lámpara de hendidura, tinción, TBUT, evaluación palpebral y pruebas dirigidas según fenotipo.', 'Urgent specialist work-up -> systemic immunomodulation when active autoimmune cicatrization -> ocular surface support -> staged surgery only when controlled.', 'Pendiente de adaptación editorial/KOL.', 'Follow-up based on severity, therapy risk and corneal involvement.', 'Seguimiento según severidad, riesgo terapéutico y afectación corneal.', 'Escalate if severe, refractory, vision-threatening, cicatrizing or steroid-dependent.', 'Escalar si severo, refractario, amenaza visual, cicatrizante o dependiente de esteroides.', 'Progressive scarring, symblepharon, persistent epithelial defect, corneal melt or acute SJS/TEN.', 'Dolor, fotofobia, pérdida visual, defecto epitelial, ulceración, cicatrización o sospecha infecciosa.', 'Educational protocol only; not individual medical advice. Verify local medicines and guidelines.', 'Protocolo educativo; no es consejo médico individual. Verificar fármacos y guías locales.', 'expert_consensus', '[{"key": "EADV_MMP_S3", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8518905/"}, {"key": "AAO_MMP_EYENET", "url": "https://www.aao.org/eyenet/article/mucous-membrane-pemphigoid-with-ocular-involvement"}]'::jsonb, 'pending_review', false, '{"block": "ocular_surface", "as_of": "2026-05-31"}'::jsonb) on conflict do nothing;
